  camera.y=clamp(camera.y+(y-camera.y)*response,0,H-H/camera.zoom);
  if(pointer.screenX!==null){pointer.x=camera.x+pointer.screenX/camera.zoom;pointer.y=camera.y+pointer.screenY/camera.zoom;}
